import os
import subprocess
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor bn_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                          torch::Tensor running_mean, torch::Tensor running_var,
                          bool training, double momentum, double eps);
"""

bn_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// ---------------------------------------------------------------------
// Kernel 1a: compute partial per-channel sum/sumsq using multiple blocks
// per channel to maximize grid occupancy on large spatial inputs.
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_partial_stats_kernel(
    const T* __restrict__ X,
    float* __restrict__ partial_sum,
    float* __restrict__ partial_sumsq,
    int N, int C, int HW,
    int blocks_per_channel)
{
    const int c = blockIdx.x;
    const int b = blockIdx.y;
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    const int64_t CHW = (int64_t)C * HW;
    const int64_t count = (int64_t)N * HW;
    auto mXc = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                           make_shape(N, HW),
                           make_stride(CHW, Int<1>{}));
    int64_t chunk = (count + blocks_per_channel - 1) / blocks_per_channel;
    int64_t start = (int64_t)b * chunk;
    int64_t end = start + chunk;
    if (end > count) end = count;
    float sum = 0.f;
    float sumsq = 0.f;
    for (int64_t idx = start + tid; idx < end; idx += nthreads) {
        int n = (int)(idx / HW);
        int hw = (int)(idx % HW);
        float v = static_cast<float>(mXc(n, hw));
        sum += v;
        sumsq += v * v;
    }
    // Warp-level reduction using shuffle instructions, followed by a
    // single block-level reduction of the (small) per-warp partials.
    // This avoids the shared-memory tree reduction's O(log2(nthreads))
    // synchronization barriers and shrinks the shared memory footprint.
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
    }
    extern __shared__ float sdata[];
    const int warp_id = tid >> 5;
    const int lane_id = tid & 31;
    const int nwarps = (nthreads + 31) >> 5;
    float* wsum = sdata;
    float* wsumsq = sdata + nwarps;
    if (lane_id == 0) {
        wsum[warp_id] = sum;
        wsumsq[warp_id] = sumsq;
    }
    __syncthreads();
    if (tid == 0) {
        float total_sum = 0.f, total_sumsq = 0.f;
        for (int w = 0; w < nwarps; ++w) {
            total_sum += wsum[w];
            total_sumsq += wsumsq[w];
        }
        atomicAdd(&partial_sum[c], total_sum);
        atomicAdd(&partial_sumsq[c], total_sumsq);
    }
}
// ---------------------------------------------------------------------
// Kernel 1a-vec4: vectorized variant of the partial stats kernel using
// float4 loads when HW is divisible by 4 and pointers are 16-byte
// aligned. This doubles/quadruples effective memory throughput for the
// memory-bound reduction pass, matching the vec4 normalization kernel.
// ---------------------------------------------------------------------
__global__ void bn_partial_stats_kernel_vec4(
    const float4* __restrict__ X,
    float* __restrict__ partial_sum,
    float* __restrict__ partial_sumsq,
    int N, int C, int HW4,
    int blocks_per_channel)
{
    const int c = blockIdx.x;
    const int b = blockIdx.y;
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    const int64_t CHW4 = (int64_t)C * HW4;
    const int64_t count4 = (int64_t)N * HW4;
    auto mXc = make_tensor(make_gmem_ptr(X + (int64_t)c * HW4),
                           make_shape(N, HW4),
                           make_stride(CHW4, Int<1>{}));
    int64_t chunk = (count4 + blocks_per_channel - 1) / blocks_per_channel;
    int64_t start = (int64_t)b * chunk;
    int64_t end = start + chunk;
    if (end > count4) end = count4;
    float sum = 0.f;
    float sumsq = 0.f;
    for (int64_t idx = start + tid; idx < end; idx += nthreads) {
        int n = (int)(idx / HW4);
        int hw4 = (int)(idx % HW4);
        float4 v = mXc(n, hw4);
        sum += v.x + v.y + v.z + v.w;
        sumsq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    // Warp-level reduction using shuffle instructions, followed by a
    // single block-level reduction of the (small) per-warp partials.
    // This avoids the shared-memory tree reduction's O(log2(nthreads))
    // synchronization barriers and shrinks the shared memory footprint.
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
    }
    extern __shared__ float sdata_v4[];
    const int warp_id = tid >> 5;
    const int lane_id = tid & 31;
    const int nwarps = (nthreads + 31) >> 5;
    float* wsum = sdata_v4;
    float* wsumsq = sdata_v4 + nwarps;
    if (lane_id == 0) {
        wsum[warp_id] = sum;
        wsumsq[warp_id] = sumsq;
    }
    __syncthreads();
    if (tid == 0) {
        float total_sum = 0.f, total_sumsq = 0.f;
        for (int w = 0; w < nwarps; ++w) {
            total_sum += wsum[w];
            total_sumsq += wsumsq[w];
        }
        atomicAdd(&partial_sum[c], total_sum);
        atomicAdd(&partial_sumsq[c], total_sumsq);
    }
}
// ---------------------------------------------------------------------
// Kernel 1b: finalize per-channel mean/var from accumulated partial sums
// and update running statistics in-place (training mode only).
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_finalize_stats_kernel(
    const float* __restrict__ partial_sum,
    const float* __restrict__ partial_sumsq,
    T* __restrict__ mean_out,
    T* __restrict__ var_out,
    T* __restrict__ running_mean,
    T* __restrict__ running_var,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    T* __restrict__ scale_out,
    T* __restrict__ shift_out,
    int C,
    int64_t count,
    float momentum,
    float eps)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float mean = partial_sum[c] / (float)count;
    float var = partial_sumsq[c] / (float)count - mean * mean;
    if (var < 0.f) var = 0.f;
    mean_out[c] = static_cast<T>(mean);
    var_out[c] = static_cast<T>(var);
    float unbiased_var = var;
    if (count > 1) {
        unbiased_var = var * (float)count / (float)(count - 1);
    }
    float rm = static_cast<float>(running_mean[c]);
    float rv = static_cast<float>(running_var[c]);
    rm = (1.f - momentum) * rm + momentum * mean;
    rv = (1.f - momentum) * rv + momentum * unbiased_var;
    running_mean[c] = static_cast<T>(rm);
    running_var[c] = static_cast<T>(rv);
    // Fused scale/shift computation: avoids a second, severely
    // underutilized single-CTA kernel launch by reusing the mean/var
    // already resident in registers here instead of round-tripping
    // them through global memory.
    float w = static_cast<float>(weight[c]);
    float b = static_cast<float>(bias[c]);
    float inv = rsqrtf(var + eps);
    float s = w * inv;
    scale_out[c] = static_cast<T>(s);
    shift_out[c] = static_cast<T>(b - mean * s);
}
// ---------------------------------------------------------------------
// Kernel 1c: precompute per-channel scale/shift from mean/var/weight/bias
// so the normalization pass only needs 2 per-channel values instead of 4,
// and avoids recomputing rsqrtf redundantly across the huge output tensor.
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_compute_scale_shift_kernel(
    const T* __restrict__ mean,
    const T* __restrict__ var,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    T* __restrict__ scale,
    T* __restrict__ shift,
    int C,
    float eps)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float m = static_cast<float>(mean[c]);
    float v = static_cast<float>(var[c]);
    float w = static_cast<float>(weight[c]);
    float b = static_cast<float>(bias[c]);
    float inv = rsqrtf(v + eps);
    float s = w * inv;
    scale[c] = static_cast<T>(s);
    shift[c] = static_cast<T>(b - m * s);
}
// ---------------------------------------------------------------------
// Kernel 2b: vectorized normalization using float4 loads/stores when
// the innermost spatial dimension (HW) is divisible by 4. This improves
// memory throughput for the memory-bound normalization pass. Uses
// precomputed per-channel scale/shift to minimize per-element work.
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_normalize_kernel_vec4(
    const float4* __restrict__ X,
    float4* __restrict__ Y,
    const T* __restrict__ scale,
    const T* __restrict__ shift,
    int N, int C, int HW4)
{
    const int64_t CHW4 = (int64_t)C * HW4;
    const int64_t total = (int64_t)N * CHW4;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;
    // Process two float4 elements per iteration to increase memory-
    // level parallelism (more independent loads/stores in flight)
    // and amortize loop/index-computation overhead for this
    // memory-bound kernel.
    int64_t idx2 = idx + stride;
    for (; idx2 < total; idx += stride * 2, idx2 += stride * 2) {
        int hw4_a = (int)(idx % HW4);
        int64_t tmp_a = idx / HW4;
        int c_a = (int)(tmp_a % C);
        (void)hw4_a;
        float4 xv_a = X[idx];
        float s_a = static_cast<float>(scale[c_a]);
        float sh_a = static_cast<float>(shift[c_a]);
        float4 yv_a;
        yv_a.x = xv_a.x * s_a + sh_a;
        yv_a.y = xv_a.y * s_a + sh_a;
        yv_a.z = xv_a.z * s_a + sh_a;
        yv_a.w = xv_a.w * s_a + sh_a;
        Y[idx] = yv_a;
        int hw4_b = (int)(idx2 % HW4);
        int64_t tmp_b = idx2 / HW4;
        int c_b = (int)(tmp_b % C);
        (void)hw4_b;
        float4 xv_b = X[idx2];
        float s_b = static_cast<float>(scale[c_b]);
        float sh_b = static_cast<float>(shift[c_b]);
        float4 yv_b;
        yv_b.x = xv_b.x * s_b + sh_b;
        yv_b.y = xv_b.y * s_b + sh_b;
        yv_b.z = xv_b.z * s_b + sh_b;
        yv_b.w = xv_b.w * s_b + sh_b;
        Y[idx2] = yv_b;
    }
    // Tail handling: at most one leftover grid-stride element when
    // the paired loop above exits.
    for (; idx < total; idx += stride) {
        int hw4 = (int)(idx % HW4);
        int64_t tmp = idx / HW4;
        int c = (int)(tmp % C);
        (void)hw4;
        float4 xv = X[idx];
        float s = static_cast<float>(scale[c]);
        float sh = static_cast<float>(shift[c]);
        float4 yv;
        yv.x = xv.x * s + sh;
        yv.y = xv.y * s + sh;
        yv.z = xv.z * s + sh;
        yv.w = xv.w * s + sh;
        Y[idx] = yv;
    }
}
// ---------------------------------------------------------------------
// Kernel 2: normalize the full (N,C,H,W) tensor using precomputed
// per-channel scale/shift.
// ---------------------------------------------------------------------
template <typename T>
__global__ void bn_normalize_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ scale,
    const T* __restrict__ shift,
    int N, int C, int HW)
{
    const int64_t CHW = (int64_t)C * HW;
    const int64_t total = (int64_t)N * CHW;
    auto mX = make_tensor(make_gmem_ptr(X),
                          make_shape(N, C, HW),
                          make_stride(CHW, (int64_t)HW, Int<1>{}));
    auto mY = make_tensor(make_gmem_ptr(Y),
                          make_shape(N, C, HW),
                          make_stride(CHW, (int64_t)HW, Int<1>{}));
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        int hw = (int)(idx % HW);
        int64_t tmp = idx / HW;
        int c = (int)(tmp % C);
        int n = (int)(tmp / C);
        float x = static_cast<float>(mX(n, c, hw));
        float s = static_cast<float>(scale[c]);
        float sh = static_cast<float>(shift[c]);
        float y = x * s + sh;
        mY(n, c, hw) = static_cast<T>(y);
    }
}
torch::Tensor bn_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                          torch::Tensor running_mean, torch::Tensor running_var,
                          bool training, double momentum, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 supported");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
    TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");
    auto x_c = x.contiguous();
    const int N = (int)x_c.size(0);
    const int C = (int)x_c.size(1);
    const int H = (int)x_c.size(2);
    const int W = (int)x_c.size(3);
    const int HW = H * W;
    TORCH_CHECK(weight.size(0) == C && bias.size(0) == C, "weight/bias size mismatch");
    TORCH_CHECK(running_mean.size(0) == C && running_var.size(0) == C, "running stats size mismatch");
    auto y = torch::empty_like(x_c);
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();
    TORCH_CHECK(running_mean.is_contiguous() && running_var.is_contiguous(), "running stats must be contiguous");
    auto& running_mean_c = running_mean; auto& running_var_c = running_var;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    torch::Tensor mean_t, var_t;
    auto scale_t = torch::empty({C}, x.options());
    auto shift_t = torch::empty({C}, x.options());
    // Determine once whether vectorized float4 memory access can be used
    // across both the statistics reduction pass and the normalization
    // pass. This requires HW to be divisible by 4 and both pointers to be
    // 16-byte aligned (contiguous NCHW tensors satisfy this in practice).
    bool use_vec4 = (HW % 4 == 0) &&
        (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0) &&
        (reinterpret_cast<uintptr_t>(y.data_ptr<float>()) % 16 == 0);
    if (training) {
        mean_t = torch::empty({C}, x.options());
        var_t = torch::empty({C}, x.options());
        const int64_t count = (int64_t)N * HW;
        const int threads = 256;
        auto partial_sum = torch::zeros({C}, x.options().dtype(at::kFloat));
        auto partial_sumsq = torch::zeros({C}, x.options().dtype(at::kFloat));
        if (use_vec4) {
            const int HW4 = HW / 4;
            const int64_t count4 = (int64_t)N * HW4;
            int blocks_per_channel = (int)((count4 + (int64_t)threads * 64 - 1) / ((int64_t)threads * 64));
            if (blocks_per_channel < 1) blocks_per_channel = 1;
            if (blocks_per_channel > 64) blocks_per_channel = 64;
            dim3 grid1((unsigned)C, (unsigned)blocks_per_channel);
            size_t shmem = 2 * ((threads + 31) / 32) * sizeof(float);
            bn_partial_stats_kernel_vec4<<<grid1, threads, shmem, stream>>>(
                reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
                partial_sum.data_ptr<float>(),
                partial_sumsq.data_ptr<float>(),
                N, C, HW4,
                blocks_per_channel
            );
            auto err0 = cudaGetLastError();
            TORCH_CHECK(err0 == cudaSuccess, "bn_partial_stats_kernel_vec4 launch failed: ", cudaGetErrorString(err0));
        } else {
            int blocks_per_channel = (int)((count + (int64_t)threads * 64 - 1) / ((int64_t)threads * 64));
            if (blocks_per_channel < 1) blocks_per_channel = 1;
            if (blocks_per_channel > 64) blocks_per_channel = 64;
            dim3 grid1((unsigned)C, (unsigned)blocks_per_channel);
            size_t shmem = 2 * ((threads + 31) / 32) * sizeof(float);
            bn_partial_stats_kernel<float><<<grid1, threads, shmem, stream>>>(
                x_c.data_ptr<float>(),
                partial_sum.data_ptr<float>(),
                partial_sumsq.data_ptr<float>(),
                N, C, HW,
                blocks_per_channel
            );
            auto err0 = cudaGetLastError();
            TORCH_CHECK(err0 == cudaSuccess, "bn_partial_stats_kernel launch failed: ", cudaGetErrorString(err0));
        }
        // Fused finalize + scale/shift computation: combines what used to
        // be two separate tiny, severely underutilized kernel launches
        // (each covering only C channels with typically a single CTA)
        // into one, cutting launch overhead for the per-channel stage
        // and avoiding an extra global-memory round trip for mean/var.
        const int threads_f = 128;
        const int blocks_f = (C + threads_f - 1) / threads_f;
        bn_finalize_stats_kernel<float><<<blocks_f, threads_f, 0, stream>>>(
            partial_sum.data_ptr<float>(),
            partial_sumsq.data_ptr<float>(),
            mean_t.data_ptr<float>(),
            var_t.data_ptr<float>(),
            running_mean_c.data_ptr<float>(),
            running_var_c.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            scale_t.data_ptr<float>(),
            shift_t.data_ptr<float>(),
            C,
            count,
            (float)momentum,
            (float)eps
        );
        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "bn_finalize_stats_kernel launch failed: ", cudaGetErrorString(err));
    } else {
        mean_t = running_mean_c;
        var_t = running_var_c;
        // Precompute per-channel scale/shift once so the memory-bound
        // normalization kernel only needs to read 2 per-channel values
        // (instead of 4) and avoids redundant rsqrtf work per element.
        const int threads_s = 128;
        const int blocks_s = (C + threads_s - 1) / threads_s;
        bn_compute_scale_shift_kernel<float><<<blocks_s, threads_s, 0, stream>>>(
            mean_t.data_ptr<float>(),
            var_t.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            scale_t.data_ptr<float>(),
            shift_t.data_ptr<float>(),
            C,
            (float)eps
        );
        auto errs = cudaGetLastError();
        TORCH_CHECK(errs == cudaSuccess, "bn_compute_scale_shift_kernel launch failed: ", cudaGetErrorString(errs));
    }
    if (use_vec4) {
        const int HW4 = HW / 4;
        const int64_t total4 = (int64_t)N * C * HW4;
        const int threads2 = 256;
        int64_t blocks2_ll = (total4 + threads2 - 1) / threads2;
        if (blocks2_ll > 65535) blocks2_ll = 65535;
        if (blocks2_ll < 1) blocks2_ll = 1;
        const int blocks2 = (int)blocks2_ll;
        bn_normalize_kernel_vec4<float><<<blocks2, threads2, 0, stream>>>(
            reinterpret_cast<const float4*>(x_c.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            scale_t.data_ptr<float>(),
            shift_t.data_ptr<float>(),
            N, C, HW4
        );
        auto err2 = cudaGetLastError();
        TORCH_CHECK(err2 == cudaSuccess, "bn_normalize_kernel_vec4 launch failed: ", cudaGetErrorString(err2));
    } else {
        const int64_t total = (int64_t)N * C * HW;
        const int threads2 = 256;
        int64_t blocks2_ll = (total + threads2 - 1) / threads2;
        if (blocks2_ll > 65535) blocks2_ll = 65535;
        if (blocks2_ll < 1) blocks2_ll = 1;
        const int blocks2 = (int)blocks2_ll;
        bn_normalize_kernel<float><<<blocks2, threads2, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            scale_t.data_ptr<float>(),
            shift_t.data_ptr<float>(),
            N, C, HW
        );
        auto err2 = cudaGetLastError();
        TORCH_CHECK(err2 == cudaSuccess, "bn_normalize_kernel launch failed: ", cudaGetErrorString(err2));
    }
    return y;
}
"""
_cutlass_dir = os.environ.get("CUTLASS_PATH", os.path.expanduser("~/.cache/cutlass_cute"))
_cutlass_include = os.path.join(_cutlass_dir, "include")
if not os.path.isfile(os.path.join(_cutlass_include, "cute", "tensor.hpp")):
    os.makedirs(os.path.dirname(_cutlass_dir), exist_ok=True)
    if not os.path.isdir(_cutlass_dir):
        subprocess.check_call([
            "git", "clone", "--depth", "1",
            "https://github.com/NVIDIA/cutlass.git", _cutlass_dir
        ])
_bn_ext = load_inline(
    name="custom_bn_ext",
    cpp_sources=[bn_cpp_decl],
    cuda_sources=[bn_cuda_src],
    functions=["bn_forward"],
    verbose=False,
    extra_include_paths=[_cutlass_include],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr", "-std=c++17"],
)
class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.momentum = 0.1
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _bn_ext.bn_forward(
            x, self.weight, self.bias,
            self.running_mean, self.running_var,
            self.training, self.momentum, self.eps
        )

